for idx in [nil, index]:
  b = &agentBrain{runner:r, codeSearch: idx != nil}
  for (name, run) in [('survey', b.Survey), ('repair', b.Repair), ('implement', b.Implement), ('resolve', b.Resolve)]:
    req = firstRequestOf(run(...))
    for x in ReadOnlyFileTools: assert declared(req)[x]
    assert without(declared(req),'find_references') == baseGrant[name] + (idx ? ['code_search'] : [])
    sys = replace(systemText(req),'find_references, ','')
    sys = name=='survey' ? removeClause(sys) : sys
    assert sys == baseSystem[name] + baseNote(baseGrant[name])
    assert !contains(userText(req),'find_references')

for idx in [nil, index]:
  a = &agentAuthor{runner:r, ws:ws, codeSearch: idx != nil}
  for (name, run) in [('prd', a.WritePRD), ('generate', a.GenerateArtifact), ('architecture', a.WriteArchitecture)]:
    req = firstRequestOf(run(...))
    for x in ReadOnlyFileTools: assert declared(req)[x]
    assert without(declared(req),'find_references') == baseGrant[name] + (idx ? ['code_search'] : [])
    for m in MutatingTools: assert !declared(req)[m]
    assert replace(systemText(req),'find_references, ','') == baseSystem[name] + baseNote(baseGrant[name])
    assert !contains(userText(req),'find_references')

